#!/usr/bin/env python3
"""One-time restructure of The Advocate's Academy: 3 courses x 3 modules (about 11 minutes each),
10 knowledge-check questions per module. Reads the current course JSONs, regroups their verified scenes,
adds new teaching scenes and questions, and writes the new files. Kept in the repo as a record."""
import json, os, re
AC = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), 'academy')
OLD = {n: json.load(open(os.path.join(AC, f'course-{n}.json'))) for n in (1, 2, 3)}
def mod(n, mid): return next(m for m in OLD[n]['modules'] if m['id'] == mid)

def T(_t, **v): return {"text": _t, "v": v}
def Q(q, o, a, why): return {'q': q, 'o': o, 'a': a, 'why': why}
def S(t, u): return {'t': t, 'u': u}

# ------------------------------------------------------------------ new teaching scenes
N = {}
N['c1-2728'] = T("Here is a document almost nobody asks to see. When a person starts dialysis, Medicare requires a form called the CMS 2728, the End Stage Renal Disease Medical Evidence Report. It records when dialysis began and the diagnosis behind it. It also asks whether the patient was informed of their kidney transplant options, and if not, why not. That one box is a record of whether anyone had the conversation. You can ask the facility for a copy. It is part of your record, and it tells you what was written about you on day one.",
    k='case', h='CMS-2728: the form filed when dialysis begins', sub='End Stage Renal Disease Medical Evidence Report', items=['Date dialysis began and primary diagnosis', 'Whether the patient was informed of transplant options', 'If not informed, the reason recorded', 'Part of the patient\'s record: you can ask for a copy'], src='CMS Form 2728')
N['c1-tests'] = T("Let me make the two kidney tests plain, because they are the language of every decision that follows. The blood test gives an estimated glomerular filtration rate, or eGFR, a rough percentage of normal filtering. Below sixty for three months or more is chronic kidney disease. Fifteen to twenty-nine is stage four. Below fifteen is kidney failure. The urine test is the albumin-to-creatinine ratio. Thirty or above means protein is leaking through, a sign of damage that can show up years before the blood number falls. One test without the other tells half the story.",
    k='tiers', title='Reading the two kidney tests', items=[{'h': 'eGFR 60+', 't': 'Normal filtering, unless the urine test shows damage'}, {'h': 'eGFR below 60', 't': 'Chronic kidney disease, if it lasts three months or more'}, {'h': 'eGFR 15 to 29', 't': 'Stage 4: time to plan dialysis access, education and transplant'}, {'h': 'eGFR below 15', 't': 'Kidney failure', 'c': 'alert'}, {'h': 'Urine ACR 30+', 't': 'Protein leaking: damage, even when eGFR looks fine'}], src='KDIGO definitions; CDC')
N['c1-kde'] = T("Now a benefit most people have never heard of. Since 2010, Medicare has covered kidney disease education for people with stage four disease: up to six sessions, on a doctor's referral, about the choices ahead, including home dialysis and transplant. After the Part B deductible, the patient pays the usual twenty percent. One national study of people who started dialysis between 2010 and 2014 found that fewer than one in a hundred had used it before their first treatment. Three thousand four hundred sixty-nine people, out of almost three hundred seventy thousand. A benefit nobody offers is a benefit that does not exist.",
    k='stats', items=[{'value': 6, 'label': 'education sessions Medicare covers at stage 4'}, {'value': 0.9, 'suffix': '%', 'label': 'of new dialysis patients had used it, 2010 to 2014'}, {'value': 3469, 'label': 'people who used it'}, {'value': 369968, 'label': 'people eligible'}], src='Medicare.gov; Shukla et al., Peritoneal Dialysis International')
N['c1-script'] = T("So here is what a strong visit sounds like, word for word, from a patient or a care partner. My filtration rate is falling. Please order a urine albumin test if I have not had one this year. Please refer me to a nephrologist, and tell me when. Am I eligible for Medicare's kidney disease education sessions? And at what point will you refer me for a transplant evaluation? Write the answers down, with the date and the name of the person who gave them. You are not being difficult. You are being the part of the system that remembers.",
    k='list', title='A strong visit, in five sentences', items=['"My filtration rate is falling."', '"Please order a urine albumin test this year."', '"Please refer me to a nephrologist. When?"', '"Am I eligible for kidney disease education?"', '"When will you refer me for transplant evaluation?"'])
N['c1-ship'] = T("You saw how valuable private insurance is to a dialysis business. That is why the source of insurance advice matters. Before you change plans, drop employer coverage, or accept premium help, get counseling from someone who has no stake in the answer. Every state has a State Health Insurance Assistance Program, called SHIP, funded by the federal government to give free, unbiased Medicare counseling. Ask the counselor to walk through what each choice means for the thirty-month period, for your drugs, and for transplant. Then decide.",
    k='compare', a={'h': 'Advice from the clinic', 'tag': 'Well meant, but not neutral', 'items': ['The business earns far more from some plans', 'May be framed around keeping coverage', 'Ask: who benefits from this choice?']}, b={'h': 'Advice from SHIP', 'tag': 'Free, federally funded, unbiased', 'items': ['No stake in which plan you pick', 'Explains Medigap, Advantage and timing', 'Find it at shiphelp.org']}, src='Administration for Community Living: SHIP')
N['c1-owner'] = T("You can check who owns your clinic in about two minutes. Medicare's Care Compare website lists every dialysis facility, its star rating, and its quality measures, and the underlying data shows the chain organization each facility belongs to. Look up your clinic, then the next two closest. You may find that every realistic option within driving distance belongs to the same company. That is worth knowing before you decide how hard to push, and where you might transfer if you need to.",
    k='flow', title='Check your clinic in two minutes', steps=['Open Care Compare: dialysis facilities', 'Enter your ZIP code', 'Find your clinic and its rating', 'Check the owner of the next two closest', 'Write it on your care map'], broken=[], note='Knowing your real alternatives changes how you negotiate.')
N['c1-settle'] = T("When you read about these cases, the words matter, so let me translate them. Resolve allegations means the company paid to end the case without a court deciding the facts. No admission of liability means the company does not concede it broke the law, and you should not say it did. A corporate integrity agreement is a contract with the Inspector General, usually for five years, that puts the company under outside review and reporting. A recall is a regulatory action on a product. Precise words protect your credibility, and they are still powerful. A four hundred and fifty million dollar payment speaks for itself.",
    k='list', title='Reading an enforcement record', items=['"Resolve allegations": paid to end the case; no court finding', '"No admission of liability": do not say they broke the law', '"Corporate integrity agreement": years of outside oversight', '"Recall": a regulatory action on a product', 'The amounts are facts. Quote them exactly.'])
N['c1-money-close'] = T("Step back and look at the whole picture from this module. A payment system that roughly covers costs on Medicare patients. A business model that makes its margin on a minority of privately insured patients. A charity channel that helps keep people on that coverage. Two companies with three quarters of the market, a long public enforcement record, and the resources to outspend reform at the ballot box. None of it is secret. It is simply scattered. Your advantage, from today, is that you have seen it assembled in one place, and you know where to check it yourself.",
    k='callout', text='Nothing in this module is secret. It is scattered. Assembled, it explains decisions that patients are told are simply "how it works."')
N['c1-idt'] = T("Fragmentation has one federal counterweight you should know by name. Every Medicare dialysis facility must assess each patient and build a written plan of care through an interdisciplinary team. The regulation lists who is on that team: at a minimum, the patient or the patient's designee if the patient chooses, a registered nurse, a physician treating the patient, a social worker, and a dietitian. Read that again. The patient is on the team. Ask when your next care plan meeting is, ask to attend, and ask for a copy of the plan. It is the closest thing this system has to one place where the whole patient is discussed.",
    k='web', title='The care-plan team, by regulation', center='Interdisciplinary team', items=['The patient, or the patient\'s designee', 'Registered nurse', 'Treating physician', 'Social worker', 'Dietitian'], src='42 CFR 494.80 (patient assessment) and 494.90 (plan of care)')
N['c1-aakh'] = T("In July 2019, the federal government set three goals for kidney care, in an executive order called Advancing American Kidney Health. Reduce the number of Americans developing kidney failure by twenty-five percent by 2030. Have eighty percent of new kidney failure patients in 2025 either dialyzing at home or receiving a transplant. And double the number of kidneys available for transplant by 2030. 2025 has come and gone. With about eighteen percent of traditional Medicare dialysis patients at home in 2024, you can measure that promise against the results yourself.",
    k='timeline', title='Advancing American Kidney Health, July 2019', items=[{'y': 'Goal 1', 't': '25% fewer Americans developing kidney failure by 2030'}, {'y': 'Goal 2', 't': '80% of new patients in 2025 at home or transplanted'}, {'y': 'Goal 3', 't': 'Twice as many kidneys available for transplant by 2030'}, {'y': '2024', 't': 'About 18% of traditional Medicare dialysis patients at home'}], src='HHS/ASPE: Advancing American Kidney Health (2019); MedPAC March 2026')

N['c2-multi'] = T("A center's answer is not the only answer. National policy allows a kidney candidate to register at more than one transplant program, often called multiple listing. It can widen the pool of offers, especially when the second program is in a different region. It has real costs: a second evaluation, travel, and the question of whether your insurance will pay for it. Some centers have their own rules about it. But patients with the means and the information do it routinely. You deserve to know it exists, and to ask both centers how they handle it.",
    k='compare', a={'h': 'One listing', 'tag': 'Most patients', 'items': ['One center\'s criteria', 'Offers through one local system', 'One evaluation to complete']}, b={'h': 'Multiple listing', 'tag': 'Allowed by national policy', 'items': ['Evaluated at a second program', 'Can widen access to offers', 'Check insurance and travel first']}, src='OPTN policy; SRTR')
N['c2-binder'] = T("Evaluations stall on paperwork more often than on medicine. So build an evaluation binder before the first visit. A current medication list. Recent lab results and your dialysis records. Proof of up-to-date cancer screenings for your age. A dental clearance letter, because many centers require one. Your vaccination record. The name and phone number of your support person, and their written commitment. And a one-page summary of your history in your own words. Ask the coordinator whether tests can be grouped onto one day. A complete binder can save months.",
    k='list', title='The evaluation binder', items=['Medication list and recent labs', 'Dialysis records and your CMS-2728', 'Cancer screenings and dental clearance', 'Vaccination record', 'Support person: name, phone, written commitment', 'One-page history in your own words'])
N['c2-partbid'] = T("The financial counselor will ask how you will pay for anti-rejection drugs, because a transplant without them fails. Here is a fact that changed in 2023. People whose Medicare was based only on kidney failure used to lose it thirty-six months after a successful transplant, and with it, their drug coverage. Since January 2023, a Medicare benefit called Part B immunosuppressive drug coverage lets eligible people keep coverage for those drugs after that point, if they have no other qualifying coverage. Patients and counselors still miss it. Say its name.",
    k='timeline', title='Paying for anti-rejection drugs', items=[{'y': 'Before 2023', 't': 'Kidney-only Medicare ended 36 months after transplant, with drug coverage'}, {'y': 'Oct 2022', 't': 'Enrollment opens for a new Part B immunosuppressive drug benefit'}, {'y': 'Jan 2023', 't': 'Coverage begins: drugs only, for people without other qualifying coverage'}, {'y': 'Today', 't': 'Ask the financial counselor about "Part B-ID" by name'}], src='CMS: Medicare Part B Immunosuppressive Drug Benefit')
N['c2-declined'] = T("If a center declines you, use a four-step response. First, get the reason in writing. Second, ask which parts of the reason can change: weight, dental work, a missing test, a support person, a financial question. Third, ask for a date to be reconsidered once those are addressed, and put that date on your calendar. Fourth, ask for your records and seek a second opinion at another program, because criteria really do differ. A no with a reason and a date is a plan. A no without either is a door someone closed and hoped you would not try again.",
    k='flow', title='When a center says no', steps=['Get the reason in writing', 'Ask what can change', 'Set a date to be reconsidered', 'Get records; seek a second program'], broken=[], note='A decline with a reason and a date is a plan.')
N['c2-notify'] = T("You also have a right to know where you stand. National transplant network policy requires programs to notify patients when they are added to the waiting list, when an evaluation is finished but they are not listed, and when they are removed for any reason other than transplant or death. A proposal to require notice when a patient moves between active and inactive status went out for public comment in 2025. And as you heard, the Medicare IOTA model now requires participating hospitals to notify patients when their list status changes. Ask for every one of these notices in writing.",
    k='list', title='Notices you are owed', items=['When you are added to the waiting list', 'When evaluation ends without listing', 'When you are removed (other than transplant or death)', 'IOTA hospitals: when your list status changes', 'Proposed nationally (2025): active / inactive changes'], src='OPTN: Require Patient Notification for Waitlist Status Changes; AHA on IOTA (May 2026)')
N['c2-inactive'] = T("Now the most important fact about the list that patients are rarely told. Being on the list is not the same as being able to receive a kidney. A candidate can be listed as inactive, sometimes called on hold, because a test expired, a weight changed, an insurance form is missing, or the team is waiting on something. Inactive candidates generally keep accruing waiting time, but they receive no organ offers. In 2024, forty-two percent of kidney candidates were inactive at the end of the year or when they left the list. Four in ten. Many of them did not know.",
    k='dots', total=100, lit=42, label='42 of every 100 kidney candidates were inactive at year-end or removal, 2024', src='OPTN/SRTR 2024 Annual Data Report: Kidney')
N['c2-ask-status'] = T("So ask three questions, every few months, in writing. Am I active or inactive on the list right now? If inactive, what exactly is needed to make me active, and who is responsible for each piece? And have any kidneys been offered for me and declined, and if so, why? The first two can be fixed with phone calls and paperwork. The third tells you how your center behaves. A patient who asks these questions regularly is a patient whose file stays on top of the pile.",
    k='list', title='Three questions, every few months', items=['"Am I active or inactive right now?"', '"If inactive: what is needed, and who owns each piece?"', '"Were any kidneys offered for me and declined? Why?"'])
N['c2-kdpi'] = T("One more choice belongs to you. Kidneys are scored by the kidney donor profile index, or KDPI. A higher score predicts a shorter working life for the kidney. Before a center can accept a kidney with a score above eighty-five for you, national policy requires your consent in advance. For some patients, especially older ones, saying yes can mean years less on dialysis. For others, waiting makes sense. Either way, it should be a decision you made with your team, not a box nobody explained.",
    k='compare', a={'h': 'Say yes to KDPI over 85', 'tag': 'Often considered for older candidates', 'items': ['More offers, often sooner', 'Kidney may not last as long', 'Can mean years less on dialysis']}, b={'h': 'Decline those offers', 'tag': 'Often considered for younger candidates', 'items': ['Wait for a longer-lasting kidney', 'Longer time on dialysis', 'Revisit the choice as things change']}, src='OPTN kidney allocation policy')
N['c2-ilda'] = T("Living donors have protections of their own, and you should know them before anyone asks. National policy requires every living donor program to give the donor an independent living donor advocate, a person whose job is the donor's interests alone, separate from the recipient's team. Donors are evaluated on their own medical and psychological health, and they can withdraw at any point, for any reason, while the program protects the confidentiality of their information. That last protection matters. It means no one has to say yes out of pressure.",
    k='list', title='Protections every living donor has', items=['An independent living donor advocate, separate from the recipient\'s team', 'Their own medical and psychosocial evaluation', 'The right to withdraw at any time', 'Confidentiality of their information'], src='OPTN living donation policy')
N['c2-ldpa'] = T("Some protections are still being fought for. Today, a living donor can face discrimination when buying life, disability or long-term care insurance. The Living Donor Protection Act would prohibit that, and would make clear that donors can use the Family and Medical Leave Act to recover. Versions have been introduced in Congress for years. In February 2026, the Senate committee on health, education, labor and pensions approved it. Check its current status before you cite it, and if it has not become law, it is exactly the kind of bill a constituent call can move.",
    k='case', h='Living Donor Protection Act (S. 1552)', sub='119th Congress · approved by the Senate HELP Committee, Feb. 2026', items=['Bars insurance discrimination against living donors', 'Clarifies FMLA leave for donation recovery', 'Introduced repeatedly over many years', 'Check status at congress.gov before citing'], src='ASTS; govinfo S. 1552 (reported)')
N['c2-ocs'] = T("Here is how fast innovation can move when the rules allow it. Warm, or normothermic, machine perfusion keeps an organ near body temperature with oxygenated fluid, so teams can watch it work before transplant. For livers, the FDA approved two such devices in 2021, and they are now used in transplant programs around the country. For kidneys in the United States, it remains in research. The science is not the only bottleneck. Approval pathways, payment, and a center's willingness to change routine all decide how long a better tool waits at the door.",
    k='timeline', title='Warm perfusion: one organ ahead of another', items=[{'y': '2009', 't': 'Cold machine perfusion trial for kidneys (NEJM)'}, {'y': '2021', 't': 'FDA approves warm perfusion devices for donor livers'}, {'y': 'Today', 't': 'Warm perfusion for kidneys still in U.S. research'}], src='FDA device approvals (2021); Moers et al., NEJM 2009')
N['c2-tdapa'] = T("And here is how the payment system shapes what reaches a patient. Medicare pays for dialysis through one bundled rate per treatment. When a genuinely new dialysis drug arrives, Medicare pays a temporary add-on for it, and for some drugs a smaller add-on for a few more years. There is a similar temporary add-on for qualifying new equipment. When the add-ons end, the cost has to fit inside the bundled payment. Ask yourself what that does to a clinic's appetite for anything new. Then ask your representatives the same question.",
    k='flow', title='How a new dialysis drug gets paid', steps=['Bundled rate per treatment', 'New drug: temporary add-on payments', 'Add-ons end', 'Cost must fit inside the bundle'], broken=[3], note='When the add-ons end, a new therapy competes with everything else for the same fixed dollars.', src='CMS ESRD Prospective Payment System (TDAPA and TPNIES)')
N['c2-ask-innov'] = T("So what does an advocate ask for? Ask your transplant center whether it uses machine perfusion, and how often. Ask whether it participates in trials of new preservation methods. Ask your representatives to fund research into organ preservation and oxygen delivery, including oxygen carriers, and to fix the payment rules that make new tools a loss for the people who would use them. And ask every claim for its evidence, including claims you hope are true.",
    k='list', title='The innovation ask', items=['Centers: "Do you use machine perfusion? How often?"', 'Centers: "Do you join preservation trials?"', 'Congress: fund organ preservation and oxygen-delivery research', 'Congress: fix payment rules that penalize new tools', 'Everyone: show the evidence'])

N['c3-990'] = T("Let me show you how to read a nonprofit's tax form in five minutes, because it will change how you hear every press release. Search the organization on ProPublica's Nonprofit Explorer. Open the most recent Form 990. Page one, Part One, shows total revenue and expenses. Part Seven lists what the top officers and highest-paid employees earn. Schedule I shows grants the organization gave away. The names of most individual donors are not public, but the organization's own website or annual report often lists corporate sponsors. Put those pieces together and you know who it answers to.",
    k='flow', title='A Form 990 in five minutes', steps=['ProPublica Nonprofit Explorer', 'Part I: revenue and expenses', 'Part VII: officer and staff pay', 'Schedule I: grants given', 'Annual report: corporate sponsors'], broken=[], note='Who funds a voice tells you which fights it will avoid.', src='IRS Form 990; ProPublica Nonprofit Explorer')
N['c3-openpay'] = T("Open Payments works the same way for doctors. Go to the federal Open Payments search, type in your nephrologist's or surgeon's name, and you will see payments and transfers of value reported by drug and device makers: meals, travel, consulting fees, research money. A payment is not proof of wrongdoing. Many excellent physicians consult. But if your doctor is recommending a specific product, it is fair, and calm, to ask whether they have a relationship with the company that makes it.",
    k='callout', text='A reported payment is not proof of wrongdoing. It is a reason to ask a calm, direct question about a recommendation.')
N['c3-posted'] = T("Two more rights you can use tomorrow. First, the rights must be visible. The regulation requires every dialysis facility to prominently display a copy of the patient's rights, including the mailing addresses and complaint telephone numbers of the state survey agency and the ESRD Network, where patients can easily see and read them. If you cannot find it, ask where it is. Second, your records. Under federal privacy law, you have the right to a copy of your medical records, and the provider generally must respond within thirty days, with one possible thirty-day extension.",
    k='list', title='Rights you can use tomorrow', items=['Patient rights posted where patients can read them', 'Posting includes state agency and ESRD Network phone numbers', 'Right to a copy of your medical records (HIPAA)', 'Response within 30 days, one 30-day extension possible'], src='42 CFR 494.70(d); HHS: Individuals\' right to access health information')
N['c3-grievance'] = T("When you put a problem in writing, use a structure the reader cannot ignore. One: what happened, with dates and names. Two: the rule it conflicts with, by citation, if you know it. Three: the harm, or the risk of harm. Four: the specific fix you are asking for. Five: a reasonable deadline for a written answer. Keep it to one page. Keep a copy. Send it in a way you can prove, such as email or the facility's grievance form with a dated receipt. Calm, specific, documented. That is the voice that gets results.",
    k='list', title='A one-page grievance', items=['1. What happened: dates, names, facts', '2. The rule it conflicts with, by citation', '3. The harm, or the risk of harm', '4. The specific fix you want', '5. A deadline for a written answer'])
N['c3-network'] = T("A few practical details about the ESRD Network, because people hesitate when they do not know what to expect. You can call or write. You can ask that your name not be shared with the facility, though anonymity can limit what the Network can investigate. Ask for a case or reference number and the name of the person handling it. The Network can work with the facility on a resolution and can refer serious problems to the state survey agency. Write down every call, just as you would at the clinic.",
    k='flow', title='Calling the ESRD Network', steps=['Call or write', 'Say whether your name may be shared', 'Get a case number and contact name', 'Network works with the facility', 'Serious issues: referral to the state agency'], broken=[])
N['c3-whys'] = T("Let me show you the five whys with a real-world pattern. Patients at a clinic keep missing their transplant evaluation appointments. Why? They have no ride. Why? The medical transportation benefit only covers dialysis trips. Why does that matter? The evaluation is at a hospital ninety minutes away, on a different day. Why is nobody solving it? No one is assigned to schedule rides for evaluations. And why not? Because referral is tracked, but completion of the evaluation is not. Now you have a fix to propose: assign an owner and track completion, not just referral.",
    k='flow', title='Five whys: missed evaluations', steps=['Patients miss evaluations', 'Why? No ride', 'Why? Benefit covers dialysis trips only', 'Why unsolved? No one owns scheduling', 'Root cause: completion is not tracked'], broken=[4], note='Fix: assign an owner and track completion, not just referral.')
N['c3-letter'] = T("When you write to an elected official, write for a busy staff member who will spend ninety seconds on it. Subject line: your town, the issue, and your ask. First sentence: who you are and that you are a constituent. Second: the problem, with one number and one human detail. Third: the specific action you want, such as cosponsoring a named bill, sending a letter to an agency, or asking a question at a hearing. Then one paragraph of evidence, your contact information, and thanks. Short letters get read. Specific asks get answered.",
    k='list', title='The ninety-second letter', items=['Subject: town, issue, ask', 'Who you are: a constituent', 'The problem: one number, one human detail', 'The ask: one specific action', 'Evidence paragraph, contact, thank you'])
N['c3-optnpc'] = T("The national transplant network has its own public comment process, separate from Medicare's. It opens comment periods, usually twice a year, on proposed changes to allocation, notification, living donation and more. Patients and families can read the proposals and comment directly on the network's website, and the committees read them. The 2025 proposal to notify patients about active and inactive status changes is one example: patient comments are part of its record.",
    k='timeline', title='Two places to comment', items=[{'y': 'Federal Register', 't': 'Medicare and other agency rules, via regulations.gov'}, {'y': 'OPTN', 't': 'Transplant network policies, usually two comment cycles a year'}, {'y': 'Your input', 't': 'Specific section, evidence, consequence, one clear ask'}], src='OPTN: Public comment; Regulations.gov')
N['c2m2-open'] = T("Welcome to the second module. You have been referred, evaluated and accepted. Now you are on the list, and the list is where many people assume the hard part is over. It is not. In this module we look at how the list really works, how many people leave it without a kidney, how many donated kidneys are never used, and the procurement system that sits upstream of all of it.", k='title', kicker='', h='The List and the Lost Kidneys', sub='Waiting time, inactive status, unused kidneys, and the organizations that recover organs')
N['c3-fmla'] = T("Care partners need protection too, and there is some. The federal Family and Medical Leave Act lets eligible employees take up to twelve weeks of unpaid, job-protected leave a year to care for a spouse, child or parent with a serious health condition. It can be taken in blocks, or intermittently, such as a few hours for appointments. Not every worker qualifies; it depends on the size of the employer and how long you have worked there. Ask your employer's human resources office in writing, and some states add paid leave on top of it.",
    k='stats', items=[{'value': 12, 'label': 'weeks of unpaid, job-protected leave'}, {'value': 12, 'label': 'month period the weeks are counted in'}, {'value': 3, 'label': 'relationships covered: spouse, child, parent'}], src='U.S. Department of Labor: Family and Medical Leave Act')
N['c3-backup'] = T("And every care partner needs a backup. The system quietly builds itself around one dependable person, and when that person gets sick, burns out, or simply has to work, the whole plan wobbles. Name a second person. Put them on the care map. Ask the patient to authorize the care team to speak with them too. Share the binder. It is not a sign of weakness. It is the same thing a hospital does for every critical role: it never relies on one person alone.",
    k='callout', text='The system leans on one dependable person. Name a second. A plan with one point of failure is not a plan.')
N['c3-story'] = T("Your story is your most powerful piece of evidence, so tell it with a shape. Sixty seconds is enough. Start with a moment, one specific scene. Then the problem behind the moment, in one sentence. Then one number that shows it is not only you. Then the change you want, and who can make it. Practice it out loud until it fits in a minute. You will use it with a reporter, a legislator, a hospital board, and a family in a waiting room who needs to hear that someone else made it through.",
    k='flow', title='A sixty-second story', steps=['One specific moment', 'The problem behind it', 'One number: it is not just you', 'The change, and who can make it'], broken=[])
N['c3-press'] = T("When should you go to the press? Usually after you have climbed the ladder and documented the response, because a reporter's first question will be, what did they say when you complained? Get the patient's clear permission for anything about their health. Privacy laws bind providers, not patients, so a patient can share their own story, but they should decide exactly what to share. Keep to what you can prove, label allegations, and bring the documents. A story backed by records lasts. A story built on anger fades by the weekend.",
    k='compare', a={'h': 'Ready for the press', 'tag': 'Ladder climbed, records in hand', 'items': ['Dated documentation', 'Written responses, or the lack of them', 'Patient consent to share']}, b={'h': 'Not yet', 'tag': 'Anger without records', 'items': ['No written complaint filed', 'Facts you cannot prove', 'Someone else\'s private details']})
N['c3-close-cert'] = T("You have finished the content of all three courses once you complete this module and its check. Take the final assessment when you are ready. Score seventy percent or better and you will earn a certificate with your own number. But the certificate is not the point. The point is the next phone call you make, the next letter you send, the next family you help find their footing. That is how this foundation measures success: not in what we know, but in what you do with it.",
    k='callout', text='The certificate is not the point. The next call, the next letter, the next family you help: that is the point.')


N['c1-home-q'] = T("If home dialysis might fit your life, the questions decide whether it ever gets offered. Ask which home options exist where you live: peritoneal dialysis, done with fluid through the belly, often overnight, and home hemodialysis. Ask where the nearest home training program is, and whether you can visit it before deciding. Ask whether a partner is required, and what support exists if you live alone. And ask, directly, why home dialysis has or has not been discussed with you. The answer to that last question tells you a great deal about the clinic.",
    k='list', title='Questions that open the door to home', items=['Which home options exist here: PD, home hemodialysis?', 'Where is the nearest home training program? Can I visit?', 'Is a partner required? What if I live alone?', 'Why has home dialysis (not) been discussed with me?'])
N['c1-discharge'] = T("One hand-off fails more than almost any other: leaving the hospital. A person on dialysis is admitted, their medicines change, their dry weight changes, and then they go back to the clinic on Monday with none of it written down where the clinic can see it. Before any hospital discharge, ask for the discharge summary and the updated medication list to be sent to the dialysis unit and the nephrologist, and carry a copy yourself. At the next treatment, ask the nurse to compare the lists line by line. Readmissions often start in that gap.",
    k='flow', title='The hospital-to-clinic hand-off', steps=['Hospital stay: medicines and weight change', 'Ask: send discharge summary to clinic and nephrologist', 'Carry your own copy', 'Next treatment: compare medication lists line by line'], broken=[1], note='About one in five hospital stays is followed by a readmission within 30 days.', src='MedPAC, March 2026')
N['c2-support'] = T("Many programs require a named support person, and many patients do not have one obvious person to name. Do not let that quietly end your evaluation. Ask the center exactly what the support person must do, and for how long. Ask whether the role can be shared by two or three people on a written schedule. Ask the transplant social worker what community and transportation resources they have used for other patients. Centers vary, and a team of neighbors with a calendar has carried many people through recovery.",
    k='list', title='If you have no single support person', items=['Ask exactly what the role requires, and for how long', 'Ask whether two or three people can share it', 'Ask the social worker about community and ride resources', 'Put the plan in writing for the team'])
N['c3-advdir'] = T("The rights section reaches further than most people realize. It includes the right to be informed about advance directives and the facility's policy on them, and the right to be informed about the facility's own policies on patient care. It protects respect, dignity, privacy, and the confidentiality of your records. And it says you may file a grievance personally, anonymously, or through a representative. When something feels wrong at a clinic, start by asking a simple question: which of my written rights does this touch? Very often, the answer is more than one.",
    k='list', title='More rights in 42 CFR 494.70', items=['Respect, dignity and recognition of individuality and personal needs: (a)(1)', 'Privacy and confidentiality in treatment and records: (a)(3), (a)(4)', 'Advance directives and the facility\'s policy: (a)(6)', 'Facility policies on patient care: (a)(8)', 'File grievances personally, anonymously or through a representative: (a)(17)'], src='42 CFR 494.70(a)')
N['c3-coi-care'] = T("Independence also matters inside your own care. Every dialysis facility has a medical director, usually a nephrologist, who is paid by the facility for that role. Physicians can also hold ownership stakes in clinics or access centers through joint ventures, which is lawful when structured within the rules, and which you saw at the center of the enforcement cases in Course 1. None of that makes a recommendation wrong. It does make it fair to ask, politely: do you have a financial relationship with this facility or this company? A good doctor will answer plainly.",
    k='callout', text='"Do you have a financial relationship with this facility or company?" It is a fair question, and a good doctor answers it plainly.')
N['c3-notebook'] = T("Dana's notebook deserves its own lesson, because it won the case. Use one notebook, paper or digital, for everything. Each entry gets the date and time, who was there, what was said, what was promised and by when. Clip every letter and printout in date order behind it. Keep a one-line index at the front of every serious issue and its status. When you need to escalate, you will not be remembering. You will be reading from a record, and everyone in the room will know the difference.",
    k='list', title='The care notebook', items=['One notebook for everything', 'Each entry: date, time, who, what was said, what was promised', 'Letters and printouts in date order', 'Front page: index of open issues and status'])

