def pick(n, mid, idxs=None): m = mod(n, mid); return [m['scenes'][i] for i in (idxs if idxs is not None else range(len(m['scenes'])))]
def quiz(n, *mids): return [q for mid in mids for q in mod(n, mid)['quiz']]
def srcs(n, *mids):
    out, seen = [], set()
    for mid in mids:
        for s in mod(n, mid)['sources']:
            if s['u'] not in seen: seen.add(s['u']); out.append(s)
    return out

c1m1 = mod(1, 'c1m1')
open1 = dict(c1m1['scenes'][0]); open1['text'] = "Welcome. I'm Jeff Parke, founder of the Cold Ischemia Foundation. Over three modules, about eleven minutes each, I'm going to take you inside a machine most people only ever see from the chair. Not the dialysis machine. The system around it. How it is paid for, who owns it, who decides, and why so many people are carried along by it instead of being served by it."
open1['v'] = dict(open1['v'], h='The Promise and the Late Arrival', sub='How kidney failure got its own Medicare program, and why so many people reach it too late')
