FIX = [("(Module 1)", "(Module 1)"), ("(Module 2)\"", "(Module 1)\""), ("(Module 3)\"", "(Module 2)\""), ("(Module 5)\"", "(Module 3)\""),
       ("This module is about the most painful number", "This part of the module is about the most painful number"),
       ("In this module you'll learn where the numbers live", "In this part of the module you'll learn where the numbers live"),
       ("The last module is about the people", "The last part of this course is about the people"),
       ("You have finished the content of all three courses once you complete this module and its check.", "When you finish this module and its knowledge check, you will have completed every lesson in this course.")]
def fixtext(o):
    t = json.dumps(o, ensure_ascii=False)
    for a, b in FIX: t = t.replace(a, b)
    return json.loads(t)

for n, mods in PLAN.items():
    c = OLD[n]
    new = []
    for j, (mid, title, scenes, qz, so) in enumerate(mods):
        scenes = fixtext(scenes)
        first = True
        for s in scenes:
            v = s.get('v', {})
            if v.get('k') == 'title' and 'kicker' in v:
                v['kicker'] = f"Course {n} · Module {j + 1}" if first else f"Module {j + 1} · continued"
                if first: v['h'] = title
                first = False
        assert scenes[0].get('v', {}).get('k') == 'title', mid
        assert len(qz) == 10, (mid, len(qz))
        seen = set(); so = [s for s in so if not (s['u'] in seen or seen.add(s['u']))]
        new.append({'id': mid, 'title': title, 'scenes': scenes, 'quiz': qz, 'sources': so})
    c['modules'] = new
    c['minutes'] = 35
    json.dump(c, open(os.path.join(AC, f'course-{n}.json'), 'w'), ensure_ascii=False, indent=1)
    print(n, [(m['id'], len(m['scenes']), sum(len((s.get('text') or '').split()) for s in m['scenes'])) for m in new])
